import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  color,
  mix,
  smoothstep,
  texture,
  fract,
  sin,
  dot,
  float,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, PointLight, Texture, SRGBColorSpace } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'journal-card-1-label';

  // --- placeholder texture wired into TSL graph synchronously ---------
  const brushedTex = new Texture();
  brushedTex.colorSpace = SRGBColorSpace;
  brushedTex.needsUpdate = true;

  const CARD_W = 1.7;
  const CARD_H = 1.0625; // matches atlas rect ratio 512:320

  const cardGeo = new PlaneGeometry(CARD_W, CARD_H);
  const cardMat = new MeshPhysicalNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
  });

  // engineered gradient: surface -> ink vertically, blended with brushed metal
  const uvNode = uv();
  const surfaceColor = color(colors.surface);
  const inkColor = color(colors.ink);
  const gradientNode = mix(surfaceColor, inkColor, smoothstep(float(0.0), float(1.0), uvNode.y));

  // subtle grain via hashed pseudo-noise
  const grainHash = fract(
    sin(dot(uvNode, vec2(12.9898, 78.233))).mul(43758.5453)
  );
  const grainNode = grainHash.mul(0.035).sub(0.0175);

  const metalSample = texture(brushedTex);
  const blended = mix(metalSample.rgb, gradientNode, 0.4).add(vec3(grainNode, grainNode, grainNode));

  cardMat.colorNode = blended;

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.name = 'journal-card-label-panel';
  root.add(cardMesh);

  // accent edge strip (<=10% of frame, uses spec accent exactly)
  const accentGeo = new PlaneGeometry(0.035, CARD_H * 0.86);
  const accentMat = new MeshPhysicalNodeMaterial({
    roughness: 0.5,
    metalness: 0.3,
    clearcoat: 0.15,
  });
  accentMat.colorNode = color(colors.accent);
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(-CARD_W / 2 + 0.04, 0, 0.005);
  root.add(accentMesh);

  // node-local rim light carrying accent hue, kept within intensity cap
  const rimLight = new PointLight(colors.accent, 0.7, 4.0);
  rimLight.position.set(0.6, 0.4, 0.8);
  root.add(rimLight);

  // --- text content -----------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0] ?? { text: 'Journal 1' };
  const fontSize = headlineItem.typography?.fontSize ?? 39;

  const headlineText = ctx.fontAtlas.createText(headlineItem.text ?? 'Journal 1', {
    fontSize,
    color: colors.paper,
    align: 'left',
  });
  headlineText.position.set(-CARD_W / 2 + 0.18, CARD_H / 2 - 0.28, 0.01);
  root.add(headlineText);

  // --- entrance motion: weighted settle, no idle loop (static composition) --
  root.scale.set(0.97, 0.97, 0.97);
  const entranceTl = gsap.timeline();
  entranceTl.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  entranceTl.fromTo(
    root.position,
    { y: root.position.y - 0.15 },
    { y: root.position.y, duration: 0.7, ease: 'power3.out' },
    0
  );

  // --- load actual texture asynchronously, mutate placeholder in place ------
  let disposed = false;
  ctx.textureLoader
    .loadTexture(config.imageUrl ?? '/prism-assets/chrome/brushed-metal.map.png')
    .then((tex) => {
      if (disposed) return;
      brushedTex.image = tex.image;
      brushedTex.wrapS = tex.wrapS;
      brushedTex.wrapT = tex.wrapT;
      brushedTex.repeat.copy(tex.repeat);
      brushedTex.offset.copy(tex.offset);
      brushedTex.needsUpdate = true;
    })
    .catch(() => {});

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    disposed = true;
    entranceTl.kill();
    cardGeo.dispose();
    cardMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    brushedTex.dispose();
    root.remove(rimLight);
    if (headlineText.userData?.cleanup) headlineText.userData.cleanup();
  };

  return root;
}
